#include <vector>
#include <cstdio>

void print_c_style(const char* data) {
    std::printf("Data: %s\n", data);
}

int main() {
    std::vector<char> v = {'H', 'e', 'l', 'l', 'o', '\0'};

    // print_c_style(v.begin()); // ERROR: Iterator type mismatch (non-portable)

    // CORRECT: Use data() or &v[0] for C APIs
    print_c_style(v.data());    // Portable since C++11
    print_c_style(&v[0]);       // Portable (requires v.size() > 0)
}
